<script setup lang="ts">
import ActionMenu from "../../components/ActionMenu.vue";
import { computed, reactive } from 'vue';
import { Head, Link, router } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import Pagination from '../../components/Pagination.vue';
import { money, type PageRows } from '../../types/salesOrder';
type Row = { id: number; status?: string; pending?: boolean; id_sales_order?: number; id_quotation: number; nomor: string; nomor_so: string; nomor_quotation: string; nomor_program: string; jenis: string; kepada_nama: string; judul: string; sales_nama: string; jumlah_peserta: number; total_tagihan: string; piutang?: string; perlakuan_ppn?: string; tanggal_bayar?: string | null; tanggal: string; closed_date?: string | null };
const props = defineProps<{ rows: PageRows<Row>; filters: Record<string, string>; tab: string; counts: { uninvoiced: number; invoiced: number }; programs: { id: number; nomor: string }[]; canAdd: boolean }>();
const f = reactive({ q: '', jenis: '', tahun: '', program: '', perlakuan_ppn: '', pembayaran: '', status: '', ...props.filters, tab: props.tab });
const search = () => router.get('/invoicing', f);
const excel = computed(() => '/invoicing/excel?' + new URLSearchParams(Object.entries(f).filter(([, value]) => value !== '').map(([key, value]) => [key, String(value)])).toString());
</script>
<template>
    <Head title="Invoicing" /><AppLayout title="Invoicing"><div class="page-head"><h1>Invoicing</h1><a :href="excel">Excel</a></div><nav class="tabs" aria-label="Status Invoicing"><Link href="/invoicing" :aria-current="tab === 'uninvoiced' ? 'page' : undefined">Uninvoiced ({{ counts.uninvoiced }})</Link><Link href="/invoicing?tab=invoiced" :aria-current="tab === 'invoiced' ? 'page' : undefined">Invoiced ({{ counts.invoiced }})</Link></nav>
        <p v-if="tab === 'uninvoiced'">SO Siap invoice, satu Invoice untuk seluruh peserta Deal. B2B All-in 1 company.</p>
        <p v-for="e in $page.props.errors" :key="String(e)" class="error" role="alert">{{ e }}</p>
        <form class="filters" @submit.prevent="search"><label>Cari<input v-model="f.q" type="search" maxlength="100" placeholder="Program, invoice, quotation, customer, sales" /></label><label>Jenis<select v-model="f.jenis"><option value="">Public &amp; B2B</option><option value="public">Public</option><option value="b2b">B2B</option></select></label><label>Program<select v-model="f.program"><option value="">Semua</option><option v-for="p in programs" :key="p.id" :value="p.id">{{ p.nomor }}</option></select></label><label>{{ tab === 'invoiced' ? 'Tahun Invoice' : 'Tahun Quotation' }}<input v-model="f.tahun" type="number" min="1900" max="2200" /></label><template v-if="tab === 'invoiced'"><label>Perlakuan PPN<select v-model="f.perlakuan_ppn"><option value="">Semua</option><option>PKP</option><option>WAPU</option><option value="KB">Kawasan Berikat</option></select></label><label>Status Invoice<select v-model="f.status"><option value="">Semua</option><option value="invoiced">Aktif</option><option value="batal">Batal</option></select></label><label>Pembayaran<select v-model="f.pembayaran"><option value="">Semua</option><option value="belum">Belum dibayar</option><option value="lunas">Lunas</option></select></label></template><button class="primary">Terapkan</button></form>
        <div class="table-wrap"><table><caption class="sr-only">Daftar Invoicing {{ tab }}</caption><thead><tr><th>Program</th><th>No. SO / Quotation</th><th>Customer / Sales</th><th>Peserta</th><th>Tagihan</th><th v-if="tab === 'invoiced'">Invoice</th><th>Aksi</th></tr></thead><tbody><tr v-for="r in rows.data" :key="r.id"><td>{{ r.nomor_program }} · {{ r.jenis.toUpperCase() }}<small>{{ r.judul }}</small></td><td>{{ r.nomor_so }}<small>{{ r.nomor_quotation }}</small></td><td>{{ r.kepada_nama }}<small>{{ r.sales_nama }}</small><small>{{ r.perlakuan_ppn }}</small></td><td>{{ r.jumlah_peserta }} Deal<small>1 Invoice</small></td><td>{{ money(r.total_tagihan) }}<small v-if="tab === 'invoiced'">Piutang {{ money(r.piutang) }}</small></td><td v-if="tab === 'invoiced'"><Link :href="`/invoicing/${r.id}`">{{ r.nomor }}</Link><small>{{ r.status === 'batal' ? 'BATAL' : 'Aktif' }}</small><small>{{ r.tanggal }} · {{ r.tanggal_bayar ? 'Lunas ' + r.tanggal_bayar : 'Belum dibayar' }}</small></td><td><template v-if="tab === 'uninvoiced'"><Link v-if="canAdd && !r.closed_date && !r.pending" :href="`/invoicing/create?id_sales_order=${r.id}`">Add Invoicing</Link><span v-else-if="r.pending">Menunggu konfirmasi ulang tuntas</span><span v-else-if="r.closed_date">Program Closed</span></template><ActionMenu v-else ><Link :href="`/invoicing/${r.id}`">Lihat Invoice</Link><a :href="`/invoicing/${r.id}/pdf`" target="_blank" rel="noopener">Print Invoice</a></ActionMenu></td></tr><tr v-if="!rows.data.length"><td :colspan="tab === 'invoiced' ? 7 : 6" class="empty">Belum ada data sesuai filter.</td></tr></tbody></table></div><Pagination :page="rows" label="Halaman Invoicing" />
    </AppLayout>
</template>
